CREATE POLICY "upload_tracks sublabel insert" ON public.upload_tracks FOR INSERT TO authenticated WITH CHECK (EXISTS (SELECT 1 FROM public.uploads u WHERE u.id = upload_tracks.upload_id AND u.sublabel_id = public.current_sublabel_id() AND u.status = 'draft'));
CREATE POLICY "upload_tracks sublabel update" ON public.upload_tracks FOR UPDATE TO authenticated USING (EXISTS (SELECT 1 FROM public.uploads u WHERE u.id = upload_tracks.upload_id AND u.sublabel_id = public.current_sublabel_id() AND u.status = 'draft')) WITH CHECK (EXISTS (SELECT 1 FROM public.uploads u WHERE u.id = upload_tracks.upload_id AND u.sublabel_id = public.current_sublabel_id() AND u.status = 'draft'));
CREATE POLICY "upload_tracks sublabel delete" ON public.upload_tracks FOR DELETE TO authenticated USING (EXISTS (SELECT 1 FROM public.uploads u WHERE u.id = upload_tracks.upload_id AND u.sublabel_id = public.current_sublabel_id() AND u.status = 'draft'));